<?php
namespace App\Services\Ticket; use App\Models\Ticket\Ticket; use App\Models\Ticket\TicketStatus; use App\Models\User; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class TicketMergeService { public function __construct(private readonly TicketActivityService $activity){} public function merge(Ticket $source,Ticket $destination,User $actor,?string $reason=null):void { if($source->is($destination)||$source->merged_into_id)throw ValidationException::withMessages(['destination'=>'Tickets cannot be merged in this state.']); DB::transaction(function()use($source,$destination,$actor,$reason):void{DB::table('ticket_merges')->insert(['source_ticket_id'=>$source->id,'destination_ticket_id'=>$destination->id,'merged_by'=>$actor->id,'reason'=>$reason,'created_at'=>now()]);$closed=TicketStatus::where('category','closed')->firstOrFail();$source->update(['merged_into_id'=>$destination->id,'status_id'=>$closed->id,'closed_at'=>now()]);$this->activity->record($source,'ticket.merged',"Merged into {$destination->ticket_number}.",$actor,metadata:['destination_id'=>$destination->public_uuid]);$this->activity->record($destination,'ticket.merge_received',"Merged {$source->ticket_number} into this ticket.",$actor,metadata:['source_id'=>$source->public_uuid]);}); } }
